package su.xash.engine.ui.downloaderimport android.content.BroadcastReceiverimport android.content.Contextimport android.content.Intentimport android.content.IntentFilterimport android.os.Buildimport android.os.Bundleimport android.os.Environmentimport android.view.LayoutInflaterimport android.view.Menuimport android.view.MenuInflaterimport android.view.MenuItemimport android.view.Viewimport android.view.ViewGroupimport android.widget.Toastimport androidx.activity.OnBackPressedCallbackimport androidx.core.view.MenuProviderimport androidx.fragment.app.Fragmentimport androidx.lifecycle.Lifecycleimport androidx.navigation.fragment.findNavControllerimport com.google.android.material.dialog.MaterialAlertDialogBuilderimport su.xash.engine.Rimport su.xash.engine.databinding.FragmentDownloadPanelBindingimport java.io.Fileclass DownloadPanelFragment : Fragment() {	private var _binding: FragmentDownloadPanelBinding? = null	private val binding get() = _binding!!	private var adapter: DownloadAdapter? = null		private val menuSourceSelectorId = View.generateViewId()	enum class DownloadSource(val brandName: String, val speedResId: Int, val urlPattern: String) {		GITLAB("GitLab", R.string.source_speed_fastest, "https://gitlab.com/steamdepot/goldsrc-valve/-/archive/{branch}/goldsrc-valve-{branch}.zip"),		GITHUB_RELEASES("GitHub Releases", R.string.source_speed_fast, "https://github.com/steamdepot/goldsrc-valve/releases/download/uploads/{branch}.zip"),		GITHUB_ARCHIVE("GitHub", R.string.source_speed_medium, "https://github.com/steamdepot/goldsrc-valve/archive/refs/heads/{branch}.zip"),		ARCHIVE_ORG("archive.org", R.string.source_speed_slow, "https://archive.org/download/goldsrc-valve/{branch}.zip");		fun getFormattedName(context: Context): String {			return "$brandName (${context.getString(speedResId)})"		}	}	private val prefs by lazy {		requireContext().getSharedPreferences("downloader_settings", Context.MODE_PRIVATE)	}	private var selectedSource: DownloadSource		get() {			val name = prefs.getString("selected_source", DownloadSource.GITLAB.name) ?: DownloadSource.GITLAB.name			return try { DownloadSource.valueOf(name) } catch (e: Exception) { DownloadSource.GITLAB }		}		set(value) {			prefs.edit().putString("selected_source", value.name).apply()		}	private val gamesList = listOf(		GameDownloadInfo("valve", "Half-Life", true, 278714959L, 6451926L, 529827940L, 9067684L),		GameDownloadInfo("gearbox", "Opposing Force", true, 143197003L, 7402783L, 275065310L, 11200080L),		GameDownloadInfo("cstrike", "Counter-Strike", true, 153860064L, 15096097L, 292340389L, 26459518L),		GameDownloadInfo("bshift", "Blue Shift", true, 174107551L, 6839837L, 291836020L, 9896000L),		GameDownloadInfo("tfc", "Team Fortress", false, 62585513L, 0L, 125934169L, 0L),		GameDownloadInfo("czero", "Condition Zero", false, 227056798L, 0L, 415108359L, 0L),		GameDownloadInfo("dmc", "Deathmatch Classic", false, 22995236L, 0L, 48239254L, 0L)	)	private val downloadReceiver = object : BroadcastReceiver() {		override fun onReceive(context: Context?, intent: Intent?) {			if (intent?.action == DownloadService.ACTION_PROGRESS) {				val status = intent.getStringExtra(DownloadService.EXTRA_STATUS)				val progress = intent.getIntExtra(DownloadService.EXTRA_PROGRESS, 0)				val stageLabel = intent.getStringExtra(DownloadService.EXTRA_STAGE_LABEL) ?: ""				val currentMb = intent.getStringExtra(DownloadService.EXTRA_CURRENT_MB) ?: ""				val totalMb = intent.getStringExtra(DownloadService.EXTRA_TOTAL_MB) ?: ""				val gameName = intent.getStringExtra(DownloadService.EXTRA_GAME_NAME) ?: ""								handleServiceUpdate(status, progress, stageLabel, currentMb, totalMb, gameName)			}		}	}	override fun onCreateView(		inflater: LayoutInflater, container: ViewGroup?, savedInstanceState: Bundle?	): View {		_binding = FragmentDownloadPanelBinding.inflate(inflater, container, false)		return binding.root	}	override fun onViewCreated(view: View, savedInstanceState: Bundle?) {		super.onViewCreated(view, savedInstanceState)		if (!DownloadService.isServiceRunning) {			val hdPrefs = requireContext().getSharedPreferences("hd_selections_prefs", Context.MODE_PRIVATE)			hdPrefs.edit().clear().apply()		}		setupRecyclerView()		setupControlButtons()		setupBackPressedLogic()		setupMenuProvider()	}	private fun setupRecyclerView() {		adapter = DownloadAdapter(gamesList) { game, isHdSelected ->			if (DownloadService.isServiceRunning) return@DownloadAdapter			checkHalfLifeRequirement(game, isHdSelected)		}		binding.downloadRecyclerView.adapter = adapter	}	private fun setupControlButtons() {		binding.btnPauseResume.setOnClickListener {			val intent = Intent(requireContext(), DownloadService::class.java).apply {				action = DownloadService.ACTION_PAUSE_RESUME			}			requireContext().startService(intent)		}		binding.btnCancelDownload.setOnClickListener {			showCancelConfirmationDialog()		}	}	private fun setupBackPressedLogic() {		requireActivity().onBackPressedDispatcher.addCallback(viewLifecycleOwner, object : OnBackPressedCallback(true) {			override fun handleOnBackPressed() {				isEnabled = false				requireActivity().onBackPressedDispatcher.onBackPressed()			}		})	}	private fun setupMenuProvider() {		requireActivity().addMenuProvider(object : MenuProvider {			override fun onCreateMenu(menu: Menu, menuInflater: MenuInflater) {				menu.clear()				val menuItem = menu.add(Menu.NONE, menuSourceSelectorId, Menu.NONE, R.string.settings_download_source)				menuItem.setIcon(R.drawable.ic_baseline_cloud_24px)				menuItem.setShowAsAction(MenuItem.SHOW_AS_ACTION_ALWAYS or MenuItem.SHOW_AS_ACTION_WITH_TEXT)			}			override fun onMenuItemSelected(menuItem: MenuItem): Boolean {				return when (menuItem.itemId) {					menuSourceSelectorId -> {						if (!DownloadService.isServiceRunning) showSourceSelectionDialog()						true					}					android.R.id.home -> {						findNavController().navigateUp()						true					}					else -> false				}			}		}, viewLifecycleOwner, Lifecycle.State.RESUMED)	}	private fun showSourceSelectionDialog() {		val sources = DownloadSource.values()		val displayItems = sources.map { it.getFormattedName(requireContext()) }.toTypedArray()		val checkedItemIndex = sources.indexOf(selectedSource)		MaterialAlertDialogBuilder(requireContext())			.setTitle(getString(R.string.dialog_select_source_title))			.setSingleChoiceItems(displayItems, checkedItemIndex) { dialog, which ->				selectedSource = sources[which]				dialog.dismiss()			}			.setNegativeButton(getString(R.string.btn_cancel), null)			.show()	}	private fun showCancelConfirmationDialog() {		if (DownloadService.lastKnownStatus == DownloadService.STATUS_DELETING || 			DownloadService.lastKnownStatus == DownloadService.STATUS_CANCELING) return		MaterialAlertDialogBuilder(requireContext())			.setTitle(getString(R.string.dialog_cancel_download_title))			.setMessage(getString(R.string.dialog_cancel_download_message))			.setPositiveButton(getString(R.string.btn_yes)) { _, _ ->				val intent = Intent(requireContext(), DownloadService::class.java).apply {					action = DownloadService.ACTION_STOP				}				requireContext().startService(intent)			}			.setNegativeButton(getString(R.string.btn_no), null)			.show()	}	private fun checkHalfLifeRequirement(game: GameDownloadInfo, isHdSelected: Boolean) {		val outputDir = File(Environment.getExternalStorageDirectory(), "xash")		val hlDir = File(outputDir, "valve")		if (game.id != "valve" && (!hlDir.exists() || hlDir.list()?.isNotEmpty() != true)) {			MaterialAlertDialogBuilder(requireContext())				.setTitle(getString(R.string.hl_required_title))				.setMessage(getString(R.string.hl_required_message, game.name))				.setPositiveButton(getString(R.string.btn_install_anyway)) { dialog, _ ->					dialog.dismiss()					checkFolderConflict(game, isHdSelected)				}				.setNegativeButton(getString(R.string.btn_cancel)) { dialog, _ ->					dialog.dismiss()				}				.setCancelable(true)				.show()		} else {			checkFolderConflict(game, isHdSelected)		}	}	private fun checkFolderConflict(game: GameDownloadInfo, isHdSelected: Boolean) {		val outputDir = File(Environment.getExternalStorageDirectory(), "xash")		val targetGameDir = File(outputDir, game.id)		if (targetGameDir.exists() && targetGameDir.list()?.isNotEmpty() == true) {			MaterialAlertDialogBuilder(requireContext())				.setTitle(getString(R.string.conflict_title))				.setMessage(getString(R.string.conflict_message))				.setPositiveButton(getString(R.string.btn_replace)) { dialog, _ ->					dialog.dismiss()					startServiceSequence(game, isHdSelected, "REPLACE")				}				.setNegativeButton(getString(R.string.btn_clean_install)) { dialog, _ ->					dialog.dismiss()					startServiceSequence(game, isHdSelected, "CLEAN_INSTALL")				}				.setNeutralButton(getString(R.string.btn_skip_existing)) { dialog, _ ->					dialog.dismiss()					startServiceSequence(game, isHdSelected, "SKIP_EXISTING")				}				.setCancelable(true)				.show()		} else {			startServiceSequence(game, isHdSelected, "REPLACE")		}	}	private fun startServiceSequence(game: GameDownloadInfo, isHdSelected: Boolean, strategy: String) {		val hdPrefs = requireContext().getSharedPreferences("hd_selections_prefs", Context.MODE_PRIVATE)		hdPrefs.edit().putBoolean("hd_${game.id}", isHdSelected).apply()		val baseUrl = selectedSource.urlPattern.replace("{branch}", game.id)		val hdUrl = if (isHdSelected) selectedSource.urlPattern.replace("{branch}", "${game.id}_hd") else ""		val intent = Intent(requireContext(), DownloadService::class.java).apply {			action = DownloadService.ACTION_START			putExtra(DownloadService.EXTRA_URL, baseUrl)			putExtra(DownloadService.EXTRA_HD_URL, hdUrl)			putExtra(DownloadService.EXTRA_GAME_ID, game.id)			putExtra(DownloadService.EXTRA_GAME_NAME, game.name)			putExtra(DownloadService.EXTRA_SIZE, game.baseSizeBytes)			putExtra(DownloadService.EXTRA_HD_SIZE, game.hdSizeBytes)			putExtra(DownloadService.EXTRA_STRATEGY, strategy)			putExtra(DownloadService.EXTRA_IS_HD, isHdSelected)		}		if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {			requireContext().startForegroundService(intent)		} else {			requireContext().startService(intent)		}		lockUi(game.name)	}	private fun restoreUiStateIfServiceRunning() {		if (DownloadService.isServiceRunning) {			lockUi(DownloadService.lastKnownGameName)			handleServiceUpdate(				DownloadService.lastKnownStatus,				DownloadService.lastKnownProgress,				DownloadService.lastKnownStageLabel,				DownloadService.lastKnownCurrentMb,				DownloadService.lastKnownTotalMb,				DownloadService.lastKnownGameName			)		} else {			unlockUi()		}	}	private fun lockUi(gameName: String) {		adapter?.setInteractionEnabled(false)		binding.progressContainer.visibility = View.VISIBLE		binding.btnPauseResume.isEnabled = true		binding.btnCancelDownload.isEnabled = true		binding.btnPauseResume.alpha = 1.0f		binding.btnCancelDownload.alpha = 1.0f	}	private fun unlockUi() {		binding.progressContainer.visibility = View.GONE		binding.downloadProgressBar.isIndeterminate = false		adapter?.setInteractionEnabled(true)	}	private fun handleServiceUpdate(status: String?, progress: Int, stageLabel: String, currentMb: String, totalMb: String, gameName: String) {		when (status) {			DownloadService.STATUS_DELETING -> {				binding.downloadProgressBar.isIndeterminate = true				binding.statusText.text = getString(R.string.downloader_deleting_format, gameName)				binding.btnPauseResume.isEnabled = false				binding.btnPauseResume.alpha = 0.35f			}			DownloadService.STATUS_CANCELING -> {				binding.downloadProgressBar.isIndeterminate = true				binding.statusText.text = getString(R.string.downloader_canceling_format, gameName)				binding.btnPauseResume.isEnabled = false				binding.btnPauseResume.alpha = 0.35f			}			DownloadService.STATUS_DOWNLOADING -> {				binding.downloadProgressBar.isIndeterminate = false				binding.downloadProgressBar.progress = progress				binding.statusText.text = getString(R.string.downloader_status_format, stageLabel, currentMb, totalMb, progress)				binding.btnPauseResume.isEnabled = true				binding.btnPauseResume.alpha = 1.0f				binding.btnPauseResume.text = getString(R.string.btn_pause)			}			DownloadService.STATUS_PAUSED -> {				binding.downloadProgressBar.isIndeterminate = false				binding.downloadProgressBar.progress = progress				binding.statusText.text = getString(R.string.downloader_status_format, stageLabel, currentMb, totalMb, progress) + " (${getString(R.string.btn_pause)})"				binding.btnPauseResume.isEnabled = true				binding.btnPauseResume.alpha = 1.0f				binding.btnPauseResume.text = getString(R.string.btn_resume)			}			DownloadService.STATUS_UNZIPPING -> {				binding.downloadProgressBar.isIndeterminate = true				binding.statusText.text = getString(R.string.downloader_extracting_format, stageLabel)				binding.btnPauseResume.isEnabled = false				binding.btnPauseResume.alpha = 0.35f			}			DownloadService.STATUS_SUCCESS -> {				unlockUi()				Toast.makeText(context, getString(R.string.download_success, gameName), Toast.LENGTH_LONG).show()			}			DownloadService.STATUS_FAILED -> {				unlockUi()				Toast.makeText(context, stageLabel.ifEmpty { getString(R.string.download_failed) }, Toast.LENGTH_LONG).show()			}		}	}	override fun onStart() {		super.onStart()		val filter = IntentFilter(DownloadService.ACTION_PROGRESS)		if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) {			requireContext().registerReceiver(downloadReceiver, filter, Context.RECEIVER_NOT_EXPORTED)		} else {			requireContext().registerReceiver(downloadReceiver, filter)		}		restoreUiStateIfServiceRunning()	}	override fun onStop() {		super.onStop()		requireContext().unregisterReceiver(downloadReceiver)	}	override fun onDestroyView() {		super.onDestroyView()		_binding = null	}}